// Vorkhive hexagon mark, extracted from public/logo.png, for use where the
// full wordmark can't fit: the centre of the card QR codes and the embedded
// PHOTO on the vCards. Generated by scripts (see scripts/gen-card-qr.mjs and
// the assets note in vorkhive-namecards memory); do not hand-edit the base64.
//
// LOGO_QR_PNG_B64   — transparent-background hexagon, sits on the QR's white badge
// LOGO_PHOTO_PNG_B64 — white-background square, the vCard contact photo
export const LOGO_QR_PNG_B64 = '';
export const LOGO_QR_DATA_URI = 'data:image/png;base64,' + LOGO_QR_PNG_B64;
export const LOGO_PHOTO_PNG_B64 = '';
